  ('60000000-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000004', 'Use uma primitiva de $3x^2$ e avalie os limites.', 1),
  ('60000000-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000005', 'Experimente integração por partes com $u=x$.', 1),
