insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values
  ('40000000-0000-4000-8000-000000000004', '$1$', 'A primitiva de $3x^2$ é $x^3$.'),
  ('40000000-0000-4000-8000-000000000005', '$(x-1)e^x+C$', 'Aplicando integração por partes, a derivada do primeiro fator diminui de $x$ para $1$.'),
  ('40000000-0000-4000-8000-000000000006', '$2$', 'Os termos de maior grau determinam o limite da razão.'),
  ('40000000-0000-4000-8000-000000000007', '$1$', 'A soma a partir de $n=1$ é $(1/2)/(1-1/2)$.') ,
  ('40000000-0000-4000-8000-000000000008', '$-5$', 'O determinante é $1\\cdot1-2\\cdot3$.'),
  ('40000000-0000-4000-8000-000000000009', '$2$ e $5$', 'Uma matriz diagonal já apresenta seus autovalores na diagonal principal.'),
  ('40000000-0000-4000-8000-000000000010', '$-1$', 'O produto escalar é $1\\cdot2+2\\cdot0+(-1)\\cdot3$.')
insert into public.question_solution_steps (id, question_id, content_markdown, sort_order) values
  ('70000000-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000004', '$[x^3]_0^1=1^3-0^3=1$.', 1),
  ('70000000-0000-4000-8000-000000000006', '40000000-0000-4000-8000-000000000005', '$\\int xe^x dx=xe^x-\\int e^x dx=(x-1)e^x+C$.', 1),
  ('70000000-0000-4000-8000-000000000007', '40000000-0000-4000-8000-000000000006', 'Dividindo por $n$, obtemos $(2+1/n)/(1+3/n)$, cujo limite é $2$.', 1),
  ('70000000-0000-4000-8000-000000000008', '40000000-0000-4000-8000-000000000007', '$\\sum_{n=1}^{\\infty}(1/2)^n=(1/2)/(1-1/2)=1$.', 1),
  ('70000000-0000-4000-8000-000000000009', '40000000-0000-4000-8000-000000000008', '$1\\cdot1-2\\cdot3=-5$.', 1),
  ('70000000-0000-4000-8000-000000000010', '40000000-0000-4000-8000-000000000009', 'A matriz é diagonal; portanto seus autovalores são $2$ e $5$.', 1),
  ('70000000-0000-4000-8000-000000000011', '40000000-0000-4000-8000-000000000010', '$2+0-3=-1$.', 1)
